import{_ as t,o as s,c as a,a2 as r}from"./chunks/framework.Zh78JZbW.js";const m=JSON.parse('{"title":"Les mots à connaître","description":"","frontmatter":{},"headers":[],"relativePath":"guide/lexique.md","filePath":"guide/lexique.md"}'),n={name:"guide/lexique.md"};function d(o,e,i,l,c,u){return s(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="les-mots-a-connaitre" tabindex="-1">Les mots à connaître <a class="header-anchor" href="#les-mots-a-connaitre" aria-label="Permalink to &quot;Les mots à connaître&quot;">​</a></h1><p>Une instance, c&#39;est une version de Minecraft + un loader + tes mods, rangés dans leur propre dossier : tu peux en avoir plusieurs, elles ne se mélangent jamais.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Kodus</span></span>
<span class="line"><span>├── Survie entre potes   1.21 · Fabric    Sodium, Iris… + shaders, resource packs</span></span>
<span class="line"><span>├── Gros modpack         1.20.1 · Forge   Create, JEI… (importé d&#39;un .kpack)</span></span>
<span class="line"><span>└── Créatif              1.21 · Vanilla   pas de mods, resource packs</span></span></code></pre></div><p>Un mod installé dans une instance n&#39;apparaît pas dans les autres : tu peux tester sans risque dans une copie.</p><table tabindex="0"><thead><tr><th>Mot</th><th>Ce que c&#39;est</th></tr></thead><tbody><tr><td>Instance</td><td>Une « installation » de Minecraft avec ses réglages, ses mods et ses mondes. Exemple : une instance Survie en 1.21 avec Fabric, une autre Créatif en Vanilla.</td></tr><tr><td>Version</td><td>La version de Minecraft (1.20.1, 1.21…). Un mod est fait pour une version précise : un mod 1.20.1 ne marche pas en 1.21.</td></tr><tr><td>Vanilla</td><td>Minecraft de base, sans mods.</td></tr><tr><td>Loader</td><td>Le programme qui permet aux mods de se charger. Un mod est fait pour un loader : un mod Fabric ne marche pas avec Forge.</td></tr><tr><td>Fabric / Quilt</td><td>Loaders légers et rapides, les plus utilisés pour les mods de performance (Sodium…). Quilt accepte la plupart des mods Fabric.</td></tr><tr><td>Forge / NeoForge</td><td>Loaders des gros mods et gros modpacks (Create, technologies, magie…). NeoForge est la suite de Forge pour les versions récentes.</td></tr><tr><td>Mod</td><td>Un ajout au jeu : contenu, interface, performances. Il se range dans le dossier <code>mods</code> de l&#39;instance.</td></tr><tr><td>Dépendance</td><td>Un mod dont un autre a besoin pour marcher (souvent Fabric API). Kodus les installe tout seul.</td></tr><tr><td>Resource pack</td><td>Change les textures, les sons ou les modèles, sans changer le gameplay. Marche même en Vanilla.</td></tr><tr><td>Shader</td><td>Change la lumière, les ombres et l&#39;eau pour un rendu très joli. Demande un PC correct et le mod Iris.</td></tr><tr><td>Datapack</td><td>Change les règles d&#39;un monde (recettes, génération…), sans mod. Il s&#39;installe dans un monde précis.</td></tr><tr><td>Modpack</td><td>Une instance toute prête (mods + réglages) qu&#39;on partage en un seul fichier : <code>.kpack</code> pour Kodus, <code>.mrpack</code> pour Modrinth.</td></tr><tr><td>Modrinth</td><td>Le site d&#39;où Kodus télécharge les mods, packs et shaders.</td></tr></tbody></table>`,5)])])}const g=t(n,[["render",d]]);export{m as __pageData,g as default};
